'use client';

import Link from 'next/link';
import { ServicesView } from '@/components/services-view';
import { useCallback, useEffect, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, Bell, CalendarDays, Check, ChevronDown, ChevronRight,
  CircleDollarSign, ClipboardList, Clock3, Computer, CreditCard, FileText, Headphones, House,
  Laptop, LayoutDashboard, LifeBuoy, ListFilter, Menu, MessageCircle, MoreHorizontal, PackageCheck,
  PanelLeftClose, Plus, Printer, Search, Settings, ShieldCheck, Sparkles, Store, Users, Wrench, X,
} from 'lucide-react';
import {
  type Appointment, type Client, type Device, type Mode, type Order, type Status, type View,
  dateLabel, DEMO_DATE, initials, isLate, money, nextStatus, normalize, nowLabel, statuses,
} from '@/lib/demo';
import { useDemo } from '@/components/demo-provider';
import { QuoteDialog } from '@/components/quote-dialog';
import { OrderApprovalPanel } from '@/components/order-approval-panel';
import { OrderStageGuide } from '@/components/order-stage-guide';
import { OrderCorrectionPanel } from '@/components/order-correction-panel';
import { PaymentDialog } from '@/components/payment-dialog';
import { AppointmentDialog } from '@/components/appointment-dialog';
import { NewOrderModal } from '@/components/new-order-modal';
import { AgendaView } from '@/components/agenda-view';
import { AppointmentDrawer } from '@/components/appointment-drawer';
import { FunctionalSettingsView } from '@/components/settings-view-functional';
import { ClientsView, ClientDetails } from '@/components/clients-view-functional';
import { ClientRegistrationModal } from '@/components/client-registration-modal';
import { DeviceRegistrationModal } from '@/components/device-registration-modal';
import { hasSupabaseConfig } from '@/lib/supabase/env';
import { createClient } from '@/lib/supabase/client';
import { type FinancialBreakdown, unclassifiedBreakdown } from '@/lib/quote-finance';
import { FinancialSummary } from '@/components/financial-summary';
import { FinanceBreakdownReport } from '@/components/finance-breakdown-report';
import { OrderTrackingPanel } from '@/components/order-tracking-panel';
import { OrderPickupAuthorizationPanel } from '@/components/order-pickup-authorization-panel';

const navItems: { key: View; label: string; icon: typeof LayoutDashboard; group?: string }[] = [
  { key: 'painel', label: 'Painel', icon: LayoutDashboard },
  { key: 'ordens', label: 'Ordens de serviço', icon: ClipboardList, group: 'Operação' },
  { key: 'clientes', label: 'Clientes', icon: Users },
  { key: 'equipamentos', label: 'Equipamentos', icon: Laptop },
  { key: 'agenda', label: 'Agenda', icon: CalendarDays },
  { key: 'orcamentos', label: 'Orçamentos', icon: FileText, group: 'Gestão' },
  { key: 'servicos', label: 'Serviços', icon: Wrench },
  { key: 'financeiro', label: 'Financeiro', icon: CircleDollarSign },
  { key: 'configuracoes', label: 'Configurações', icon: Settings, group: 'Sistema' },
];
const viewTitles: Record<View, { title: string; description: string; eyebrow: string }> = {
  painel: { title: 'Bom dia, Marina', description: 'Aqui está o que merece atenção hoje na Matriz · Centro.', eyebrow: 'Segunda-feira, 28 de setembro de 2026' },
  ordens: { title: 'Ordens de serviço', description: 'Acompanhe cada atendimento do recebimento à entrega.', eyebrow: 'Operação' },
  clientes: { title: 'Clientes', description: 'Histórico, contatos e equipamentos em um só lugar.', eyebrow: 'Relacionamento' },
  equipamentos: { title: 'Equipamentos', description: 'Identifique e encontre rapidamente tudo que passou pela assistência.', eyebrow: 'Ativos' },
  agenda: { title: 'Agenda da equipe', description: 'Organize visitas, sessões remotas e retiradas sem sobreposição.', eyebrow: 'Operação' },
  orcamentos: { title: 'Orçamentos', description: 'Propostas que aguardam resposta e histórico de aprovações.', eyebrow: 'Gestão' },
  servicos: { title: 'Serviços', description: 'Cadastre serviços com código e preço padrão de mão de obra.', eyebrow: 'Gestão' },
  financeiro: { title: 'Financeiro', description: 'Visão simples dos valores a receber e dos recebimentos registrados.', eyebrow: 'Gestão' },
  configuracoes: { title: 'Configurações', description: 'Ajustes da assistência, equipe e preferências da operação.', eyebrow: 'Sistema' },
};
const modeIcon: Record<Mode, typeof Store> = { Balcão: Store, Remoto: Headphones, Domicílio: House };

function IconButton({ label, onClick, children, className = '' }: { label: string; onClick?: () => void; children: React.ReactNode; className?: string }) { return <button className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick}>{children}</button>; }
function ModePill({ mode }: { mode: Mode }) { const Icon = modeIcon[mode]; return <span className={`mode-pill mode-${normalize(mode)}`}><Icon size={14} />{mode}</span>; }
function StatusPill({ status, late = false }: { status: Status; late?: boolean }) { return <span className={`status-pill status-${normalize(status)} ${late ? 'late' : ''}`}><span className="status-dot" />{late ? 'Atrasada · ' : ''}{status}</span>; }
function PaymentStatusPill({ order }: { order: Order }) { const state = order.amount > 0 && order.paid >= order.amount ? 'paid' : order.paid > 0 ? 'partial' : 'pending'; const label = state === 'paid' ? 'Pagamento concluído' : state === 'partial' ? 'Pagamento parcial' : 'Pagamento pendente'; return <span className={`status-pill payment-status payment-${state}`}><span className="status-dot" />{label}</span>; }
function Avatar({ name, small = false }: { name: string; small?: boolean }) { return <span className={`avatar ${small ? 'small' : ''}`} aria-label={name}>{initials(name)}</span>; }
function PageHeading({ view, onNew, userName, onShortcuts }: { onShortcuts: () => void; view: View; onNew: () => void; userName: string }) { const { title: defaultTitle, description, eyebrow } = viewTitles[view]; const title = view === 'painel' ? (userName === 'Usuário conectado' ? 'Painel da assistência' : `Bom dia, ${userName.split(' ')[0]}`) : defaultTitle; return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="heading-actions"><button className="button ghost hide-mobile" onClick={onShortcuts}><span>⌘</span> Atalhos</button>{view !== 'configuracoes' && view !== 'servicos' && <button className="button primary" onClick={onNew}><Plus size={18} /> Novo atendimento</button>}</div></div>; }

export function Workspace({ view: initialView }: { view: View }) {
  const { data, ready, notify, reset } = useDemo();
  const liveMode = hasSupabaseConfig();
  const [userName, setUserName] = useState(liveMode ? 'Usuário conectado' : 'Marina Azevedo');
  const [userRole, setUserRole] = useState(liveMode ? 'Conta autenticada' : 'Gestora');
  const [liveResources, setLiveResources] = useState<{ clients: Client[]; devices: Device[]; orders: Order[]; appointments: Appointment[]; quotes: Array<{ id: string; serviceOrderId: string; version: number; status: string; totalCents: number; validUntil: string | null }> } | null>(null);
  const [liveLoading, setLiveLoading] = useState(liveMode);
  const [liveError, setLiveError] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [orderClientId, setOrderClientId] = useState('');
  const [orderDeviceId, setOrderDeviceId] = useState('');
  const [shortcutsOpen, setShortcutsOpen] = useState(false);
  useEffect(() => { function shortcut(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.querySelector<HTMLInputElement>('[aria-label="Buscar no sistema"]')?.focus(); } if (event.key === 'Escape') setShortcutsOpen(false); } window.addEventListener('keydown', shortcut); return () => window.removeEventListener('keydown', shortcut); }, []);
  const [view, setView] = useState(initialView);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  const [modal, setModal] = useState<'order' | 'client' | 'device' | 'quote' | 'payment' | 'appointment' | null>(null);
  const [quoteOrderId, setQuoteOrderId] = useState('');
  const [paymentOrderId, setPaymentOrderId] = useState('');
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const deviceId = params.get('deviceId');
    if (params.get('new') !== '1' || !deviceId) return;
    setOrderClientId(params.get('clientId') ?? '');
    setOrderDeviceId(deviceId);
    setModal('order');
  }, []);
  useEffect(() => {
    if (!liveMode) return;
    const supabase = createClient();
    void (async () => {
      const { data: authData } = await supabase.auth.getUser();
      if (!authData.user) return;
      const [{ data: profile }, { data: membership }] = await Promise.all([
        supabase.from('profiles').select('full_name').eq('id', authData.user.id).maybeSingle(),
        supabase.from('unit_memberships').select('role').eq('user_id', authData.user.id).eq('is_active', true).limit(1).maybeSingle(),
      ]);
      setUserName(profile?.full_name?.trim() || authData.user.user_metadata?.full_name || authData.user.email?.split('@')[0] || 'Usuário conectado');
      const roleLabels: Record<string, string> = { gestor: 'Gestora', atendimento: 'Atendimento', tecnico: 'Técnico', financeiro: 'Financeiro' };
      setUserRole(roleLabels[membership?.role ?? ''] ?? 'Equipe');
    })();
  }, [liveMode]);
  const refreshLiveResources = useCallback(async () => {
    if (!liveMode) return;
    setLiveLoading(true);
    setLiveError('');
    try {
      const [clientsResponse, devicesResponse, ordersResponse, quotesResponse, appointmentsResponse] = await Promise.all([fetch('/api/clients'), fetch('/api/devices'), fetch('/api/orders'), fetch('/api/quotes'), fetch('/api/appointments')]);
      if (!clientsResponse.ok || !devicesResponse.ok || !ordersResponse.ok || !quotesResponse.ok || !appointmentsResponse.ok) { throw new Error('Não foi possível carregar os dados. Tente novamente.'); }
      const clientsPayload = await clientsResponse.json() as { data?: Array<{ id: string; full_name: string; phone: string; email?: string | null; tax_id?: string; document_type?: 'cpf' | 'cnpj'; legal_name?: string; trade_name?: string; notes?: string; address?: { postal_code?: string; street?: string; number?: string; complement?: string; neighborhood?: string; city?: string; state?: string } | null }> };
      const devicesPayload = await devicesResponse.json() as { data?: Array<{ id: string; client_id: string; code: string; kind: string; brand: string; model: string; serial?: string | null; notes?: string | null }> };
      const ordersPayload = await ordersResponse.json() as { data?: Array<{ id: string; number: string; client_id: string; device_id?: string | null; mode: Mode; status: Status; priority: string; issue: string; accessories?: string | null; due_date?: string | null; amount_cents: number; paid_cents: number; created_at: string; financialBreakdown?: FinancialBreakdown }> };
      const quotesPayload = await quotesResponse.json() as { data?: Array<{ id: string; service_order_id: string; version: number; status: string; total_cents: number; valid_until?: string | null }> };
      const appointmentsPayload = await appointmentsResponse.json() as { data?: Array<{ id: string; service_order_id: string; client_id: string; mode: Mode; title: string; start_at: string; end_at: string }> };
      setLiveResources({
        clients: (clientsPayload.data ?? []).map(client => ({ id: client.id, taxId: client.tax_id ?? '', documentType: client.document_type ?? 'cpf', legalName: client.legal_name ?? '', tradeName: client.trade_name ?? '', notes: client.notes ?? '', addressFields: { postalCode: client.address?.postal_code ?? '', street: client.address?.street ?? '', number: client.address?.number ?? '', complement: client.address?.complement ?? '', neighborhood: client.address?.neighborhood ?? '', city: client.address?.city ?? '', state: client.address?.state ?? '' }, name: client.full_name, phone: client.phone, email: client.email ?? '', address: client.address ? [client.address.street, client.address.number, client.address.neighborhood, client.address.city, client.address.state].filter(Boolean).join(', ') : '' })),
        devices: (devicesPayload.data ?? []).map(item => ({ id: item.id, clientId: item.client_id, code: item.code, kind: item.kind, brand: item.brand, model: item.model, serial: item.serial ?? '', notes: item.notes ?? '' })),
        orders: (ordersPayload.data ?? []).map(order => ({ id: order.id, createdAt: order.created_at, number: order.number, clientId: order.client_id, deviceId: order.device_id ?? '', mode: order.mode, status: order.status, priority: order.priority, technician: 'Equipe', issue: order.issue, due: order.due_date ?? DEMO_DATE, amount: order.amount_cents, financialBreakdown: order.financialBreakdown, paid: order.paid_cents, accessories: order.accessories ?? '', history: [], contacts: [] })),
        appointments: (appointmentsPayload.data ?? []).map(appointment => { const start = new Date(appointment.start_at); const end = new Date(appointment.end_at); return { id: appointment.id, orderId: appointment.service_order_id, date: start.toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' }), time: start.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false }), duration: Math.max(15, Math.round((end.getTime() - start.getTime()) / 60000)), technician: 'Equipe', title: appointment.title, mode: appointment.mode, address: '' }; }),
        quotes: (quotesPayload.data ?? []).map(quote => ({ id: quote.id, serviceOrderId: quote.service_order_id, version: quote.version, status: quote.status, totalCents: quote.total_cents, validUntil: quote.valid_until ?? null })),
      });
    } catch { setLiveError('Não foi possível atualizar os dados. Verifique sua conexão e tente novamente.'); }
    finally { setLiveLoading(false); }
  }, [liveMode]);
  useEffect(() => { const timer = window.setTimeout(() => { void refreshLiveResources(); }, 0); return () => window.clearTimeout(timer); }, [refreshLiveResources]);
  const resourceData = liveResources ? { ...data, clients: liveResources.clients, devices: liveResources.devices, orders: liveResources.orders } : liveMode ? { ...data, clients: [], devices: [], orders: [] } : data;
  const clientName = (id: string) => resourceData.clients.find(c => c.id === id)?.name ?? 'Cliente não encontrado';
  const device = (id: string) => resourceData.devices.find(d => d.id === id);
  function navigate(next: View) { setView(next); setMobileOpen(false); setSearch(''); window.history.replaceState(null, '', next === 'painel' ? '/' : `/${next}`); }
  function openOrder(order: Order) { setSelectedOrder(order); }
  function onNew() { setOrderClientId(''); setOrderDeviceId(''); setModal('order'); }
  return <div className="app-shell">
    <Sidebar active={view} onNavigate={navigate} mobileOpen={mobileOpen} onClose={() => setMobileOpen(false)} reset={reset} orderCount={resourceData.orders.length} dataMode={liveResources ? 'live' : liveMode && liveLoading ? 'connecting' : 'demo'} />
    <div className="main-shell">
      <header className="topbar"><div className="mobile-brand"><span className="brand-mark small-mark">N</span><b>Nexo</b></div><IconButton label="Abrir menu" className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu size={21} /></IconButton><div className="global-search"><Search size={17} /><input aria-label="Buscar no sistema" placeholder="Buscar cliente, OS ou equipamento" value={search} onChange={event => setSearch(event.target.value)} /><kbd>⌘ K</kbd></div><div className="topbar-actions"><button className="unit-switcher"><span className="unit-icon"><Store size={16} /></span><span className="hide-mobile">Matriz · Centro</span><ChevronDown size={15} /></button><IconButton label="Notificações"><Bell size={19} /><span className="notification-dot" /></IconButton><div className="user-profile"><Avatar name={userName} small /><span className="user-meta"><b>{userName}</b><small>{userRole}</small></span><ChevronDown size={15} /></div></div></header>
      <main className="content"><PageHeading view={view} userName={userName} onNew={onNew} onShortcuts={() => setShortcutsOpen(true)} />{!ready && <div className="loading-bar" aria-label="Carregando demonstração" />}<SearchResults query={search} data={resourceData} onOrder={openOrder} onClient={client => { navigate('clientes'); setSelectedClient(client); }} />{view === 'painel' && <Dashboard data={resourceData} clientName={clientName} device={device} appointmentsOverride={liveResources?.appointments ?? null} onOrder={openOrder} onNavigate={navigate} onNew={onNew} />}{view === 'ordens' && <OrdersView data={resourceData} search={search} clientName={clientName} device={device} onOrder={openOrder} onNew={onNew} />}{view === 'clientes' && <ClientsView data={resourceData} search={search} liveLoading={liveLoading} loadError={liveError} onRetry={() => void refreshLiveResources()} onNew={() => setModal('client')} onClient={setSelectedClient} />}{view === 'equipamentos' && <DevicesView data={resourceData} search={search} clientName={clientName} devicesOverride={liveResources?.devices ?? null} clientsOverride={liveResources?.clients ?? null} liveLoading={liveLoading} onNew={() => setModal('device')} />}{view === 'agenda' && <AgendaView data={resourceData} clientName={clientName} appointmentsOverride={liveResources?.appointments ?? null} onNew={() => setModal('appointment')} onSelect={setSelectedAppointment} />}{view === 'orcamentos' && <QuotesView data={resourceData} clientName={clientName} quotesOverride={liveResources?.quotes ?? null} onOrder={openOrder} notify={notify} onNew={() => { setQuoteOrderId(''); setModal('quote'); }} />}{view === 'servicos' && <ServicesView liveMode={liveMode} notify={notify} />}{view === 'financeiro' && <FinanceView data={resourceData} clientName={clientName} onOrder={openOrder} onNew={() => setModal('payment')} />}{view === 'configuracoes' && <FunctionalSettingsView notify={notify} reset={reset} liveMode={liveMode} />}</main>
    </div>
    {shortcutsOpen && <Modal title="Atalhos" description="Navegue mais rápido pelo sistema." close={() => setShortcutsOpen(false)}><p><kbd>Ctrl / ⌘ + K</kbd> — Buscar no sistema</p><p><kbd>Esc</kbd> — Fechar a janela atual</p></Modal>}
    {selectedClient && <ClientDetails client={resourceData.clients.find(item => item.id === selectedClient.id) ?? selectedClient} data={resourceData} liveMode={liveMode} close={() => setSelectedClient(null)} notify={notify} onUpdated={() => { setSelectedClient(null); void refreshLiveResources(); }} onOrder={order => { setSelectedClient(null); openOrder(order); }} onNewOrder={client => { setSelectedClient(null); setOrderClientId(client.id); setModal('order'); }} />}
    {selectedOrder && <OrderDrawer order={selectedOrder} data={resourceData} liveMode={liveMode} onUpdated={() => void refreshLiveResources()} onOpenQuote={() => { setQuoteOrderId(selectedOrder.id); setSelectedOrder(null); setModal('quote'); }} onOpenPayment={() => { setPaymentOrderId(selectedOrder.id); setSelectedOrder(null); setModal('payment'); }} close={() => setSelectedOrder(null)} notify={notify} />}
    {selectedAppointment && <AppointmentDrawer appointment={selectedAppointment} data={resourceData} liveMode={liveMode} onUpdated={() => void refreshLiveResources()} close={() => setSelectedAppointment(null)} notify={notify} />}
    {modal === 'order' && <NewOrderModal initialClientId={orderClientId} initialDeviceId={orderDeviceId} data={resourceData} liveMode={liveMode} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'client' && <NewClientModal liveMode={liveMode} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'device' && <DeviceRegistrationModal data={resourceData} liveMode={liveMode} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'quote' && <QuoteDialog orders={resourceData.orders} initialOrderId={quoteOrderId} liveMode={liveMode} onCreated={() => { void refreshLiveResources(); if (quoteOrderId) setSelectedOrder(resourceData.orders.find(order => order.id === quoteOrderId) ?? null); }} close={() => setModal(null)} notify={notify} />}{modal === 'payment' && <PaymentDialog orders={resourceData.orders} initialOrderId={paymentOrderId} liveMode={liveMode} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}{modal === 'appointment' && <AppointmentDialog orders={resourceData.orders} liveMode={liveMode} onCreated={() => void refreshLiveResources()} close={() => setModal(null)} notify={notify} />}
  </div>;
}

function Sidebar({ active, onNavigate, mobileOpen, onClose, reset, orderCount, dataMode }: { active: View; onNavigate: (view: View) => void; mobileOpen: boolean; onClose: () => void; reset: () => void; orderCount: number; dataMode: 'demo' | 'connecting' | 'live' }) { const modeLabel = dataMode === 'live' ? 'Dados conectados' : dataMode === 'connecting' ? 'Conectando ao banco' : 'Modo demonstração'; return <><div className={`sidebar-backdrop ${mobileOpen ? 'visible' : ''}`} onClick={onClose} /><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="brand"><span className="brand-mark">N</span><span><b>Nexo</b><small>gestão da assistência</small></span><IconButton label="Fechar menu" className="sidebar-close" onClick={onClose}><PanelLeftClose size={18} /></IconButton></div><div className="demo-tag"><Sparkles size={14} /><span>{modeLabel}</span></div><nav>{navItems.map((item, index) => <div key={item.key}>{item.group && <span className="nav-group">{item.group}</span>}<button className={`nav-item ${active === item.key ? 'active' : ''}`} onClick={() => onNavigate(item.key)}><item.icon size={18} strokeWidth={active === item.key ? 2.3 : 1.8} /><span>{item.label}</span>{item.key === 'ordens' && orderCount > 0 && <span className="nav-count">{orderCount}</span>}</button>{index === 0 && <div className="nav-separator" />}</div>)}</nav><div className="sidebar-footer"><div className="help-card"><div className="help-icon"><LifeBuoy size={17} /></div><div><b>Precisa de ajuda?</b><span>Veja como funciona</span></div><ChevronRight size={16} /></div><button className="nav-item" onClick={() => { reset(); onClose(); }}><ShieldCheck size={18} /><span>Restaurar demonstração</span></button><div className="sidebar-version">v0.1 · etapa 1 <span>·</span> sem WhatsApp</div></div></aside></>; }

function SearchResults({ query, data, onOrder, onClient }: { query: string; data: ReturnType<typeof useDemo>['data']; onOrder: (order: Order) => void; onClient: (client: Client) => void }) { if (!query.trim() || query.trim().length < 2) return null; const q = normalize(query); const clients = data.clients.filter(c => normalize(c.name).includes(q) || normalize(c.phone).includes(q)).slice(0, 3); const orders = data.orders.filter(o => normalize(o.number).includes(q) || normalize(o.issue).includes(q)).slice(0, 3); if (!clients.length && !orders.length) return <div className="search-popover"><Search size={18} /><span>Nenhum resultado para <b>{query}</b></span></div>; return <div className="search-popover"><span className="popover-label">Resultados rápidos</span>{clients.map(client => <button key={client.id} onClick={() => onClient(client)}><Avatar name={client.name} small /><span><b>{client.name}</b><small>Cliente · {client.phone}</small></span><ChevronRight size={15} /></button>)}{orders.map(order => <button key={order.id} onClick={() => onOrder(order)}><span className="search-order">{order.number}</span><span><b>{data.clients.find(c => c.id === order.clientId)?.name}</b><small>OS · {order.status}</small></span><ChevronRight size={15} /></button>)}</div>; }

function Dashboard({ data, clientName, device, appointmentsOverride, onOrder, onNavigate, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; device: (id: string) => Device | undefined; appointmentsOverride?: Appointment[] | null; onOrder: (o: Order) => void; onNavigate: (v: View) => void; onNew: () => void }) { const late = data.orders.filter(isLate); const waiting = data.orders.filter(o => o.status === 'Aguardando aprovação'); const due = data.orders.filter(o => o.paid < o.amount && o.status !== 'Concluído'); const dueTotal = due.reduce((sum, o) => sum + o.amount - o.paid, 0); const today = (appointmentsOverride ?? data.appointments).filter(a => a.date === DEMO_DATE); return <div className="dashboard-grid"><section className="hero-card"><div className="hero-orb orb-one" /><div className="hero-orb orb-two" /><div className="hero-content"><span className="hero-kicker"><span className="pulse-dot" /> Visão da operação · atualizada agora</span><h2>Seu dia, <em>sob controle.</em></h2><p>Há <b>{late.length} atendimentos atrasados</b> e <b>{waiting.length} orçamentos</b> aguardando resposta.</p><div className="hero-actions"><button className="button light" onClick={() => onNavigate('ordens')}>Ver pendências <ArrowDownRight size={16} /></button><button className="text-button light-text" onClick={() => onNew()}>Abrir atendimento <Plus size={15} /></button></div></div><div className="hero-stat"><span>Receita em aberto</span><strong>{money(dueTotal)}</strong><small><ArrowUpRight size={14} /> 12,8% <i>vs. mês anterior</i></small></div></section><div className="metric-row"><Metric icon={<ClipboardList />} label="Em andamento" value={String(data.orders.filter(o => !['Concluído', 'Pronto para entrega'].includes(o.status)).length)} detail="+2 esta semana" trend="up" color="blue" /><Metric icon={<Clock3 />} label="Prazo vencido" value={String(late.length).padStart(2, '0')} detail="Requer atenção" trend="down" color="orange" /><Metric icon={<PackageCheck />} label="Prontos para entrega" value={String(data.orders.filter(o => o.status === 'Pronto para entrega').length).padStart(2, '0')} detail="Hoje" trend="neutral" color="green" /><Metric icon={<CircleDollarSign />} label="A receber" value={money(dueTotal)} detail="6 clientes" trend="up" color="purple" /></div><section className="panel recent-panel"><PanelHeader title="Acompanhe as OS" subtitle="Últimas movimentações" link="Ver todas" onLink={() => onNavigate('ordens')} /><div className="table-wrap"><table><thead><tr><th>Ordem</th><th>Cliente</th><th>Equipamento</th><th>Status</th><th>Responsável</th><th aria-label="Ações" /></tr></thead><tbody>{data.orders.slice(0, 5).map(order => <OrderRow key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</tbody></table></div><div className="mobile-order-list">{data.orders.slice(0, 5).map(order => <OrderCard key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</div></section><div className="bottom-grid"><section className="panel agenda-panel"><PanelHeader title="Agenda de hoje" subtitle={dateLabel(DEMO_DATE)} link="Abrir agenda" onLink={() => onNavigate('agenda')} /><div className="agenda-list">{today.map(item => <AppointmentItem key={item.id} appointment={item} />)}</div><button className="add-dashed" onClick={onNew}><Plus size={16} /> Adicionar compromisso</button></section><section className="panel attention-panel"><PanelHeader title="Atenção" subtitle="O que precisa de você" /><div className="attention-list"><AttentionItem icon={<FileText />} tone="violet" title={`${waiting.length} orçamentos sem resposta`} detail="O mais antigo há 2 dias" onClick={() => onNavigate('orcamentos')} /><AttentionItem icon={<AlertTriangle />} tone="orange" title={`${late.length} OS passaram do prazo`} detail="Verifique os responsáveis" onClick={() => onNavigate('ordens')} /><AttentionItem icon={<CircleDollarSign />} tone="green" title={`${due.length} recebimentos pendentes`} detail={`Total de ${money(dueTotal)}`} onClick={() => onNavigate('financeiro')} /></div></section></div></div>; }
function Metric({ icon, label, value, detail, trend, color }: { icon: React.ReactNode; label: string; value: string; detail: string; trend: string; color: string }) { return <div className="metric-card"><span className={`metric-icon ${color}`}>{icon}</span><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small className={trend === 'up' ? 'positive' : trend === 'down' ? 'negative' : ''}>{trend === 'up' && <ArrowUpRight size={13} />}{trend === 'down' && <ArrowDownRight size={13} />}{detail}</small></div><MoreHorizontal size={17} className="metric-more" /></div>; }
function PanelHeader({ title, subtitle, link, onLink, linkClassName = '' }: { title: string; subtitle?: string; link?: string; onLink?: () => void; linkClassName?: string }) { return <div className="panel-header"><div><h3>{title}</h3>{subtitle && <span>{subtitle}</span>}</div>{link && <button className={`panel-link ${linkClassName}`} onClick={onLink}>{link} <ChevronRight size={15} /></button>}</div>; }
function OrderRow({ order, clientName, device, onClick }: { order: Order; clientName: (id: string) => string; device?: Device; onClick: () => void }) { return <tr onClick={onClick} className="clickable-row"><td><b className="order-number">{order.number}</b><small className={isLate(order) ? 'late-text' : ''}>{isLate(order) ? `Venceu em ${dateLabel(order.due)}` : `Previsto para ${dateLabel(order.due)}`}</small></td><td><span className="person-cell"><Avatar name={clientName(order.clientId)} small /><b>{clientName(order.clientId)}</b></span></td><td><span className="device-cell"><Laptop size={15} />{device?.brand} {device?.model}</span><small className="code-label">{device?.code}</small></td><td><div className="status-stack"><StatusPill status={order.status} late={isLate(order)} /><PaymentStatusPill order={order} /></div></td><td><span className="person-cell"><Avatar name={order.technician} small /><b>{order.technician}</b></span></td><td><ChevronRight size={17} className="row-chevron" /></td></tr>; }
function OrderCard({ order, clientName, device, onClick }: { order: Order; clientName: (id: string) => string; device?: Device; onClick: () => void }) { return <button className="order-card" onClick={onClick}><div><span className="order-number">{order.number}</span><span className="status-stack"><StatusPill status={order.status} late={isLate(order)} /><PaymentStatusPill order={order} /></span></div><b>{clientName(order.clientId)}</b><span>{device?.brand} {device?.model} · {device?.code}</span><ChevronRight size={17} /></button>; }
function AppointmentItem({ appointment }: { appointment: Appointment }) { const Icon = modeIcon[appointment.mode]; return <div className="appointment-item"><span className="time-label">{appointment.time}</span><div className={`appointment-line ${normalize(appointment.mode)}`} /><div className="appointment-info"><div><b>{appointment.title}</b><ModePill mode={appointment.mode} /></div><span>{appointment.technician}{appointment.address && ` · ${appointment.address}`}</span></div><Icon size={17} className="appointment-type" /></div>; }
function AttentionItem({ icon, tone, title, detail, onClick }: { icon: React.ReactNode; tone: string; title: string; detail: string; onClick: () => void }) { return <button className="attention-item" onClick={onClick}><span className={`attention-icon ${tone}`}>{icon}</span><span><b>{title}</b><small>{detail}</small></span><ChevronRight size={16} /></button>; }

function OrdersView({ data, search, clientName, device, onOrder, onNew }: { data: ReturnType<typeof useDemo>['data']; search: string; clientName: (id: string) => string; device: (id: string) => Device | undefined; onOrder: (o: Order) => void; onNew: () => void }) { const [filter, setFilter] = useState<'all' | Status>('all'); const [mode, setMode] = useState<'list' | 'board'>('list'); const filtered = data.orders.filter(o => { const q = normalize(search); const matches = !q || [o.number, o.issue, clientName(o.clientId), device(o.deviceId)?.code ?? ''].some(value => normalize(value).includes(q)); return matches && (filter === 'all' || o.status === filter); }); return <div className="view-stack"><div className="view-toolbar"><div className="filter-pills"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>Todas <span>{data.orders.length}</span></button>{statuses.slice(0, 6).map(status => <button key={status} className={filter === status ? 'selected' : ''} onClick={() => setFilter(status)}>{status}<span>{data.orders.filter(o => o.status === status).length}</span></button>)}</div><div className="toolbar-actions"><button className="button secondary"><ListFilter size={16} /> Filtros</button><div className="segmented"><button className={mode === 'list' ? 'on' : ''} onClick={() => setMode('list')}><ClipboardList size={16} /></button><button className={mode === 'board' ? 'on' : ''} onClick={() => setMode('board')}><Activity size={16} /></button></div></div></div>{mode === 'list' ? <section className="panel full-panel"><div className="table-wrap"><table><thead><tr><th>Ordem</th><th>Cliente</th><th>Equipamento</th><th>Modalidade</th><th>Status</th><th>Responsável</th><th /></tr></thead><tbody>{filtered.map(order => <OrderRow key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</tbody></table></div><div className="mobile-order-list">{filtered.map(order => <OrderCard key={order.id} order={order} clientName={clientName} device={device(order.deviceId)} onClick={() => onOrder(order)} />)}</div>{!filtered.length && <EmptyState title="Nenhuma OS encontrada" text="Ajuste os filtros ou abra um novo atendimento." action="Novo atendimento" onClick={onNew} />}</section> : <Board orders={filtered} clientName={clientName} device={device} onOrder={onOrder} />}</div>; }
function Board({ orders, clientName, device, onOrder }: { orders: Order[]; clientName: (id: string) => string; device: (id: string) => Device | undefined; onOrder: (o: Order) => void }) { return <div className="kanban">{statuses.slice(0, 6).map(status => <section className="kanban-column" key={status}><header><span className="kanban-title"><i className={`status-dot dot-${normalize(status)}`} />{status}</span><span>{orders.filter(o => o.status === status).length}</span></header>{orders.filter(o => o.status === status).map(order => <button className="kanban-card" key={order.id} onClick={() => onOrder(order)}><div><b>{order.number}</b>{order.priority === 'Alta' && <span className="priority-high">Alta</span>}</div><strong>{clientName(order.clientId)}</strong><span>{device(order.deviceId)?.brand} {device(order.deviceId)?.model}</span><footer><Avatar name={order.technician} small /><small>{order.technician}</small><span>{dateLabel(order.due)}</span></footer></button>)}<button className="kanban-add"><Plus size={14} /> Adicionar</button></section>)}</div>; }


function DevicesView({ data, search, clientName, devicesOverride, clientsOverride, liveLoading, onNew }: { data: ReturnType<typeof useDemo>['data']; search: string; clientName: (id: string) => string; devicesOverride?: Device[] | null; clientsOverride?: Client[] | null; liveLoading?: boolean; onNew: () => void }) { const q = normalize(search); const devicesSource = devicesOverride ?? data.devices; const clientsSource = clientsOverride ?? data.clients; const resolveClientName = (id: string) => clientsSource.find(c => c.id === id)?.name ?? clientName(id); const devices = devicesSource.filter(d => !q || [d.code, d.brand, d.model, resolveClientName(d.clientId)].some(v => normalize(v).includes(q))); return <div className="view-stack"><div className="list-toolbar"><span>{liveLoading ? 'Carregando equipamentos…' : `${devices.length} equipamentos identificados`}</span><div>{devicesOverride && <Link href="/equipamentos/etiquetas" className="button secondary"><Printer size={16} /> Folha Pimaco 6280</Link>}<button className="button secondary"><ListFilter size={16} /> Filtrar</button><button className="button primary" onClick={onNew}><Plus size={17} /> Novo equipamento</button></div></div><section className="device-grid">{devices.map(d => { const orders = data.orders.filter(o => o.deviceId === d.id); const current = orders[orders.length - 1]; return <article className="panel device-card" key={d.id}><div className="device-card-top"><span className="equipment-code">{d.code}</span><span className="device-card-actions">{devicesOverride && <Link href={`/equipamentos/${d.id}/etiqueta`} className="plain-icon" aria-label="Imprimir etiqueta"><FileText size={17} /></Link>}{devicesOverride && <Link href={`/equipamentos/${d.id}/etiqueta#fotos`} className="device-photos-link">Fotos</Link>}</span></div><div className="device-visual"><Computer size={42} strokeWidth={1.25} /></div><div className="device-card-body"><span className="eyebrow">{d.kind}</span><h3>{d.brand} {d.model}</h3><p>{resolveClientName(d.clientId)}</p><div className="device-details"><span><span className="detail-label">Série</span>{d.serial}</span><span><span className="detail-label">Atendimentos</span>{orders.length}</span></div>{current && <div className="device-current"><span>Último atendimento</span><b>{current.number} · {current.status}</b></div>}</div></article>; })}</section>{!devices.length && <EmptyState title="Nenhum equipamento encontrado" text="Use o código de quatro caracteres, marca ou cliente." action="Novo equipamento" onClick={onNew} />}</div>; }


function QuotesView({ data, clientName, quotesOverride, onOrder, notify, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; quotesOverride?: Array<{ id: string; serviceOrderId: string; version: number; status: string; totalCents: number; validUntil: string | null }> | null; onOrder: (o: Order) => void; notify: (message: string, error?: boolean) => void; onNew?: () => void }) { const live = quotesOverride !== null && quotesOverride !== undefined; const liveQuotes = quotesOverride ?? []; const demoQuotes = data.orders.filter(o => ['Aguardando aprovação', 'Em execução', 'Concluído'].includes(o.status)); const approvalCount = live ? liveQuotes.filter(q => q.status === 'sent').length : data.orders.filter(o => o.status === 'Aguardando aprovação').length; const total = live ? liveQuotes.reduce((sum, q) => sum + q.totalCents, 0) : demoQuotes.reduce((sum, o) => sum + o.amount, 0); return <div className="view-stack"><div className="quote-summary"><div><span>Em aprovação</span><b>\${approvalCount}</b><small>aguardando retorno</small></div><div><span>Valor proposto</span><b>{money(total)}</b><small>em orçamentos ativos</small></div><div><span>Taxa de aprovação</span><b>—</b><small>dados reais em consolidação</small></div></div><section className="panel full-panel"><PanelHeader title="Propostas recentes" subtitle="Versões válidas e pendentes" link="Novo orçamento" onLink={onNew} /><div className="quote-list">{live ? liveQuotes.map(quote => { const order = data.orders.find(item => item.id === quote.serviceOrderId); return <div className="quote-row" key={quote.id}><button className="quote-main-action" style={{ flex: 1, minWidth: 0, border: 0, padding: 0, background: 'transparent', display: 'flex', alignItems: 'center', gap: 12, textAlign: 'left', color: 'inherit', cursor: 'pointer' }} onClick={() => order && onOrder(order)} disabled={!order}><span className="quote-icon"><FileText size={18} /></span><span className="quote-main"><b>{order?.number ?? 'OS vinculada'}</b><strong>{order ? clientName(order.clientId) : 'Cliente não encontrado'}</strong><small>Versão {quote.version} · {quote.validUntil ? 'válida até ' + dateLabel(quote.validUntil) : 'sem validade definida'}</small></span><span className="quote-value"><b>{money(quote.totalCents)}</b><small>valor total</small></span><span className="status-pill status-orange"><span className="status-dot" />{quote.status}</span></button><PortalLinkAction quoteId={quote.id} enabled={quote.status === 'sent'} notify={notify} /></div>; }) : demoQuotes.map(o => <button className="quote-row" key={o.id} onClick={() => onOrder(o)}><span className="quote-icon"><FileText size={18} /></span><span className="quote-main"><b>{o.number}</b><strong>{clientName(o.clientId)}</strong><small>Versão 1 · enviada em 26/09/2026</small></span><span className="quote-value"><b>{money(o.amount)}</b><small>Validade: 7 dias</small></span><StatusPill status={o.status} /><ChevronRight size={17} /></button>)}</div></section></div>; }

function PortalLinkAction({ quoteId, enabled, notify }: { quoteId: string; enabled: boolean; notify: (message: string, error?: boolean) => void }) { const [busy, setBusy] = useState(false); async function createLink() { if (!enabled || busy) return; setBusy(true); try { const response = await fetch(`/api/quotes/${quoteId}/portal-link`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ expiresInDays: 7 }) }); const result = await response.json() as { data?: { url: string }; error?: string }; if (!response.ok || !result.data?.url) { notify(result.error ?? 'Não foi possível gerar o link do portal.', true); return; } await navigator.clipboard.writeText(result.data.url); notify('Link de aprovação copiado para a área de transferência.'); } catch { notify('Não foi possível gerar o link do portal.', true); } finally { setBusy(false); } } return <button className="button secondary compact" type="button" disabled={!enabled || busy} onClick={event => { event.stopPropagation(); void createLink(); }}>{busy ? 'Gerando…' : 'Copiar link'}</button>; }
function FinanceView({ data, clientName, onOrder, onNew }: { data: ReturnType<typeof useDemo>['data']; clientName: (id: string) => string; onOrder: (o: Order) => void; onNew?: () => void }) { const open = data.orders.filter(o => o.amount > o.paid && o.status !== 'Concluído'); const received = data.orders.reduce((sum, o) => sum + o.paid, 0); return <div className="view-stack"><div className="finance-cards"><Metric icon={<CircleDollarSign />} label="A receber" value={money(open.reduce((s, o) => s + o.amount - o.paid, 0))} detail="em aberto" trend="up" color="purple" /><Metric icon={<CreditCard />} label="Recebido no mês" value={money(received)} detail="+8,4% vs. anterior" trend="up" color="green" /><Metric icon={<ArrowDownRight />} label="Em atraso" value={money(open.filter(isLate).reduce((s, o) => s + o.amount - o.paid, 0))} detail={`${open.filter(isLate).length} clientes`} trend="down" color="orange" /></div><FinanceBreakdownReport orders={data.orders} clientName={clientName} onOrder={onOrder} /><section className="panel full-panel"><PanelHeader title="Valores pendentes" subtitle="Recebimentos registrados e saldo por OS" link="Registrar recebimento" onLink={onNew} linkClassName="payment-action" /><div className="table-wrap"><table><thead><tr><th>OS</th><th>Cliente</th><th>Total</th><th>Recebido</th><th>Saldo</th><th>Situação</th><th /></tr></thead><tbody>{open.map(o => <tr className="clickable-row" key={o.id} onClick={() => onOrder(o)}><td><b className="order-number">{o.number}</b></td><td>{clientName(o.clientId)}</td><td>{money(o.amount)}</td><td>{money(o.paid)}</td><td><b>{money(o.amount - o.paid)}</b></td><td><span className={`status-pill ${isLate(o) ? 'late' : 'status-orange'}`}><span className="status-dot" />{isLate(o) ? 'Atrasado' : 'Pendente'}</span></td><td><ChevronRight size={17} /></td></tr>)}</tbody></table></div></section></div>; }

function EmptyState({ title, text, action, onClick }: { title: string; text: string; action: string; onClick: () => void }) { return <div className="empty-state"><span className="empty-icon"><Search size={22} /></span><h3>{title}</h3><p>{text}</p><button className="button primary" onClick={onClick}><Plus size={16} /> {action}</button></div>; }

function OrderDrawer({ order, data, liveMode = false, onUpdated, onOpenQuote, onOpenPayment, close, notify }: { order: Order; data: ReturnType<typeof useDemo>['data']; liveMode?: boolean; onUpdated?: () => void; onOpenQuote: () => void; onOpenPayment: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { const client = data.clients.find(c => c.id === order.clientId); const device = data.devices.find(d => d.id === order.deviceId); const { commit } = useDemo(); const [tab, setTab] = useState<'overview' | 'history'>('overview'); const [saving, setSaving] = useState(false); const [history, setHistory] = useState(order.history); const loadDetails = useCallback(async () => { if (!liveMode) return; try { const response = await fetch(`/api/orders/${order.id}`); if (!response.ok) return; const result = await response.json() as { data?: { events?: Array<{ description: string; created_at: string }> } }; setHistory((result.data?.events ?? []).map(event => ({ text: event.description, at: new Date(event.created_at).toLocaleString('pt-BR') }))); } catch { /* preserve current drawer state when details are unavailable */ } }, [liveMode, order.id]); useEffect(() => { const timer = window.setTimeout(() => { void loadDetails(); }, 0); return () => window.clearTimeout(timer); }, [loadDetails]); const next = nextStatus(order); const lastContact = [...history].reverse().find(item => item.text.startsWith('Link do orçamento')); const nextLabel = order.status === 'Recebido' ? 'Iniciar diagnóstico' : order.status === 'Em execução' ? 'Enviar para testes' : order.status === 'Em testes' ? (order.mode === 'Balcão' ? 'Marcar pronto para entrega' : 'Concluir atendimento') : order.status === 'Pronto para entrega' ? 'Concluir após entrega' : next ? `Avançar para ${next}` : ''; async function advance(note?: string) { if (!next) return notify('Esta OS já está na última etapa.'); setSaving(true); if (liveMode) { try { const response = await fetch(`/api/orders/${order.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: next, note }) }); const result = await response.json() as { error?: string }; if (!response.ok) return notify(result.error ?? 'Não foi possível atualizar a OS.', true); notify(`OS ${order.number} atualizada para ${next}.`); onUpdated?.(); close(); } catch { notify('Não foi possível conectar ao servidor.', true); } finally { setSaving(false); } return; } commit(current => ({ ...current, orders: current.orders.map(o => o.id === order.id ? { ...o, status: next, history: [...o.history, { text: note ?? `Etapa atualizada para ${next}.`, at: nowLabel() }] } : o) }), `OS ${order.number} atualizada para ${next}.`); setSaving(false); close(); } return <><div className="drawer-backdrop" onClick={close} /><aside className="order-drawer"><header><div><span className="eyebrow">Ordem de serviço</span><h2>{order.number}</h2></div><IconButton label="Fechar detalhes" onClick={close}><X size={20} /></IconButton></header><div className="drawer-scroll"><div className="drawer-title-row"><StatusPill status={order.status} late={isLate(order)} /><PaymentStatusPill order={order} /><ModePill mode={order.mode} />{order.priority === 'Alta' && <span className="priority-high">Prioridade alta</span>}</div><div className="drawer-client"><Avatar name={client?.name ?? ''} /><div><b>{client?.name}</b><span>{client?.phone} · {client?.email}</span></div><button className="button secondary compact" onClick={() => { if (!client?.phone) return notify('Telefone não informado.', true); void navigator.clipboard.writeText(client.phone).then(() => notify('Telefone copiado.')).catch(() => notify('Não foi possível copiar o telefone.', true)); }}> <MessageCircle size={15} /> Contatar</button></div><div className="drawer-tabs"><button className={tab === 'overview' ? 'active' : ''} onClick={() => setTab('overview')}>Resumo</button><button className={tab === 'history' ? 'active' : ''} onClick={() => setTab('history')}>Histórico <span>{history.length}</span></button></div>{tab === 'overview' ? <><OrderStageGuide status={order.status} /><OrderCorrectionPanel order={order} devices={data.devices} liveMode={liveMode} onUpdated={onUpdated} close={close} notify={notify} onDemoChange={(change, description) => commit(current => ({ ...current, orders: current.orders.map(item => item.id === order.id ? { ...item, ...change, history: [...item.history, { text: description, at: nowLabel() }] } : item) }), description)} />{['Diagnóstico', 'Aguardando aprovação'].includes(order.status) && <OrderApprovalPanel order={order} liveMode={liveMode} onCreateQuote={onOpenQuote} onAdvance={note => void advance(note)} notify={notify} />}{['Em execução', 'Em testes', 'Pronto para entrega', 'Concluído'].includes(order.status) && <OrderExecutionPanel orderId={order.id} liveMode={liveMode} notify={notify} />}<OrderTrackingPanel orderId={order.id} orderNumber={order.number} liveMode={liveMode} notify={notify} /><OrderPickupAuthorizationPanel orderId={order.id} orderNumber={order.number} liveMode={liveMode} notify={notify} onCompleted={() => { onUpdated?.(); close(); }} /><div className="drawer-section"><div className="section-label"><Laptop size={16} /> Equipamento</div><div className="equipment-drawer-card"><span className="equipment-code">{device?.code}</span><div><b>{device?.brand} {device?.model}</b><span>{device?.kind} · Série {device?.serial}</span></div><ChevronRight size={17} /></div></div><div className="drawer-section"><div className="section-label"><Wrench size={16} /> Solicitação</div><p className="issue-text">{order.issue}</p><div className="detail-grid"><span><small>Responsável</small><b><Avatar name={order.technician} small /> {order.technician}</b></span><span><small>Prazo estimado</small><b className={isLate(order) ? 'late-text' : ''}>{dateLabel(order.due)} {isLate(order) && '· atrasado'}</b></span><span><small>Valor previsto</small><b>{order.amount ? money(order.amount) : 'A definir pelo orçamento'}</b></span><span><small>Saldo pendente</small><b>{order.amount ? money(order.amount - order.paid) : '—'}</b></span></div></div><div className="drawer-section"><div className="section-label"><CircleDollarSign size={16} /> Composição do valor</div><FinancialSummary breakdown={order.financialBreakdown ?? unclassifiedBreakdown(order.amount)} /><div className="payment-summary"><div><span>Total</span><b>{money(order.amount)}</b></div><div><span>Recebido</span><b>{money(order.paid)}</b></div><div><span>Saldo</span><b>{money(Math.max(0, order.amount - order.paid))}</b></div><button className="button payment-action" onClick={onOpenPayment} disabled={order.amount <= order.paid}>Adicionar pagamento</button></div></div><div className="drawer-section"><div className="section-label"><MessageCircle size={16} /> Último contato</div>{order.contacts.length ? <div className="contact-note"><span className="note-channel">{order.contacts[0].channel}</span><p>{order.contacts[0].text}</p><small>{order.contacts[0].at}</small></div> : lastContact ? <div className="contact-note"><span className="note-channel">Proposta enviada</span><p>{lastContact.text}</p><small>{lastContact.at}</small></div> : <div className="empty-note">Nenhum contato registrado ainda.</div>}</div></> : <div className="timeline">{history.map((item, i) => <div className="timeline-item" key={`${item.at}-${i}`}><span className="timeline-dot" /><div><b>{item.text}</b><small>{item.at}</small></div></div>)}</div>}</div><footer className="drawer-footer"><Link className="button secondary" href={`/ordens/${order.id}/comprovante`} target="_blank">Imprimir</Link>{next && !['Diagnóstico', 'Aguardando aprovação'].includes(order.status) && <button className="button primary" disabled={saving} onClick={() => void advance()}>{saving ? 'Atualizando…' : <>{nextLabel} <ChevronRight size={16} /></>}</button>}</footer></aside></>; }

function OrderExecutionPanel({ orderId, liveMode, notify }: { orderId: string; liveMode: boolean; notify: (message: string, error?: boolean) => void }) { const [tasks, setTasks] = useState<Array<{ id: string; label: string; completed: boolean }>>([]); const [attachments, setAttachments] = useState<Array<{ id: string; file_name: string; url: string | null }>>([]); const [newTask, setNewTask] = useState(''); const [busy, setBusy] = useState(false); const load = useCallback(async () => { if (!liveMode) return; try { const [tasksResponse, attachmentsResponse] = await Promise.all([fetch(`/api/orders/${orderId}/tasks`), fetch(`/api/orders/${orderId}/attachments`)]); if (tasksResponse.ok) { const result = await tasksResponse.json() as { data?: Array<{ id: string; label: string; completed: boolean }> }; setTasks(result.data ?? []); } if (attachmentsResponse.ok) { const result = await attachmentsResponse.json() as { data?: Array<{ id: string; file_name: string; url: string | null }> }; setAttachments(result.data ?? []); } } catch { /* keep the drawer usable if optional details fail */ } }, [liveMode, orderId]); useEffect(() => { const timer = window.setTimeout(() => { void load(); }, 0); return () => window.clearTimeout(timer); }, [load]); async function addTask(event: React.FormEvent) { event.preventDefault(); if (!newTask.trim() || !liveMode) return; setBusy(true); try { const response = await fetch(`/api/orders/${orderId}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ label: newTask.trim(), position: tasks.length }) }); if (!response.ok) { const result = await response.json() as { error?: string }; notify(result.error ?? 'Não foi possível adicionar a atividade.', true); return; } setNewTask(''); await load(); } finally { setBusy(false); } } async function toggleTask(task: { id: string; completed: boolean }) { if (!liveMode) return; const response = await fetch(`/api/orders/${orderId}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: !task.completed }) }); if (response.ok) await load(); else notify('Não foi possível atualizar a atividade.', true); } async function upload(event: React.ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file || !liveMode) return; setBusy(true); const form = new FormData(); form.append('file', file); try { const response = await fetch(`/api/orders/${orderId}/attachments`, { method: 'POST', body: form }); const result = await response.json() as { error?: string }; if (!response.ok) notify(result.error ?? 'Não foi possível anexar o arquivo.', true); else { notify('Arquivo anexado à OS.'); await load(); } } finally { setBusy(false); event.target.value = ''; } } return <div className="drawer-section"><div className="section-label"><Check size={16} /> Execução</div>{liveMode ? <><div className="timeline">{tasks.map(task => <label className="preference" key={task.id}><span><b className={task.completed ? 'muted' : ''}>{task.label}</b><small>{task.completed ? 'Concluída' : 'Pendente'}</small></span><input type="checkbox" checked={task.completed} onChange={() => void toggleTask(task)} /></label>)}</div><form className="inline-form" onSubmit={addTask}><input value={newTask} onChange={event => setNewTask(event.target.value)} placeholder="Adicionar atividade ou teste" /><button className="button secondary compact" disabled={busy || !newTask.trim()}>Adicionar</button></form><label className="button secondary compact" style={{ display: 'inline-flex', marginTop: 10, cursor: 'pointer' }}>{busy ? 'Enviando…' : 'Anexar arquivo'}<input type="file" hidden accept="image/jpeg,image/png,image/webp,application/pdf,text/plain" onChange={upload} disabled={busy} /></label>{attachments.length > 0 && <div className="contact-note">{attachments.map(file => file.url ? <a href={file.url} target="_blank" rel="noreferrer" key={file.id}>{file.file_name}</a> : <span key={file.id}>{file.file_name}</span>)}</div>}</> : <div className="empty-note">Checklist e anexos ficam disponíveis quando a OS estiver conectada ao Supabase.</div>}</div>; }

function NewClientModal(props: { liveMode?: boolean; onCreated?: () => void; close: () => void; notify: (message: string, error?: boolean) => void }) { return <ClientRegistrationModal {...props} />; }

function Modal({ title, description, close, children }: { title: string; description: string; close: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" onMouseDown={event => event.target === event.currentTarget && close()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span className="eyebrow">Nexo · demonstração</span><h2 id="modal-title">{title}</h2><p>{description}</p></div><IconButton label="Fechar janela" onClick={close}><X size={20} /></IconButton></header><div className="modal-body">{children}</div></section></div>; }




